import React, { useState, useEffect } from 'react';

// Lightweight store to push UI components or text to the HUD
class HUDStore {
  constructor() {
    this.state = {
      messages: [],
      activeComponent: null, // Could be a custom React node sent by the agent
    };
    this.listeners = new Set();
  }

  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  pushMessage(text, type = 'info') {
    const msg = { id: Date.now(), text, type };
    this.state.messages.push(msg);
    if (this.state.messages.length > 3) this.state.messages.shift();
    this.notify();

    setTimeout(() => {
      this.state.messages = this.state.messages.filter(m => m.id !== msg.id);
      this.notify();
    }, 5000);
  }

  setComponent(component) {
    this.state.activeComponent = component;
    this.notify();
  }

  clearComponent() {
    this.state.activeComponent = null;
    this.notify();
  }

  notify() {
    this.listeners.forEach(l => l({ ...this.state }));
  }
}

export const hudStore = new HUDStore();

export const GenerativeHUD = () => {
  const [hudState, setHudState] = useState(hudStore.state);

  useEffect(() => {
    return hudStore.subscribe(setHudState);
  }, []);

  return (
    <div className="absolute top-0 left-0 w-full h-full pointer-events-none z-50 p-8 flex flex-col justify-between">
      {/* Top Right: Agent Messages */}
      <div className="flex flex-col items-end gap-2">
        {hudState.messages.map((msg) => (
          <div key={msg.id} className="bg-black/60 backdrop-blur-md border border-cyan-500/30 text-cyan-50 px-4 py-2 rounded-lg shadow-lg animate-fade-in-right">
            <span className="font-mono text-xs text-cyan-400 mr-2">[{msg.type.toUpperCase()}]</span>
            {msg.text}
          </div>
        ))}
      </div>

      {/* Center/Bottom: Generative Components */}
      {hudState.activeComponent && (
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-auto">
          {hudState.activeComponent}
        </div>
      )}
    </div>
  );
};

export default GenerativeHUD;
