import { useState, useEffect } from 'react';

// A lightweight reactive store for user intent that avoids React Context re-renders
class IntentStore {
  constructor() {
    this.state = {
      currentZone: 'intro',
      zoneDwellTime: 0, // seconds
      mouseVariance: 0, // indicates confusion/searching if high
      isErraticScrolling: false,
      inferredIntent: 'browsing', // 'browsing', 'engaged', 'confused'
    };
    this.listeners = new Set();
    
    // Internal trackers
    this.lastZoneChange = Date.now();
    this.mousePositions = [];
    this.lastScrollTime = Date.now();
    this.scrollEvents = [];
    
    this.startTracking();
  }

  getState() {
    return this.state;
  }

  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  updateState(newState) {
    let changed = false;
    for (const key in newState) {
      if (this.state[key] !== newState[key]) {
        this.state[key] = newState[key];
        changed = true;
      }
    }
    if (changed) {
      this.state = { ...this.state };
      this.listeners.forEach((listener) => listener(this.state));
    }
  }

  setZone(zoneName) {
    if (this.state.currentZone !== zoneName) {
      this.lastZoneChange = Date.now();
      this.updateState({ currentZone: zoneName, zoneDwellTime: 0 });
    }
  }

  startTracking() {
    // 1. Dwell Time and Mouse Variance Loop
    setInterval(() => {
      const dwell = Math.floor((Date.now() - this.lastZoneChange) / 1000);
      
      // Calculate variance here once per second instead of every mousemove
      let currentVariance = this.state.mouseVariance;
      if (this.mousePositions.length === 20) {
        let dx = 0; let dy = 0;
        for (let i = 1; i < this.mousePositions.length; i++) {
          dx += Math.abs(this.mousePositions[i].x - this.mousePositions[i-1].x);
          dy += Math.abs(this.mousePositions[i].y - this.mousePositions[i-1].y);
        }
        currentVariance = dx + dy;
      }
      
      let intent = 'browsing';
      if (dwell > 15 && currentVariance < 50) {
        intent = 'engaged'; // Reading, focused
      } else if (dwell > 10 && currentVariance > 150) {
        intent = 'confused'; // Moving mouse rapidly, not scrolling away
      }

      this.updateState({ 
        zoneDwellTime: dwell,
        inferredIntent: intent,
        mouseVariance: currentVariance
      });
    }, 1000);

    // 2. Mouse Tracking (Only collect data, DO NOT trigger React state updates)
    if (typeof window !== 'undefined') {
      window.addEventListener('mousemove', (e) => {
        this.mousePositions.push({ x: e.clientX, y: e.clientY, t: Date.now() });
        if (this.mousePositions.length > 20) this.mousePositions.shift();
      });
    }
  }
}

export const userIntentStore = new IntentStore();

// React Hook
export function useUserIntent() {
  const [state, setState] = useState(
    (typeof userIntentStore !== 'undefined' && userIntentStore) ? userIntentStore.getState() : {
      currentZone: 'intro',
      zoneDwellTime: 0,
      mouseVariance: 0,
      isErraticScrolling: false,
      inferredIntent: 'browsing',
    }
  );

  useEffect(() => {
    if (typeof userIntentStore !== 'undefined' && userIntentStore) {
      return userIntentStore.subscribe(setState);
    }
  }, []);

  return state;
}
