import React, { useRef, useState, useEffect } from 'react';
import { useUserIntent } from '../UserIntentEngine';
import { useFrame } from '@react-three/fiber';
import { Html, Text } from '@react-three/drei';
import * as THREE from 'three';

/**
 * AvatarSystem - Simulates a HeyGem.ai Photorealistic Avatar + OmniVoice TTS + Handy STT
 */
export const AvatarSystem = ({ position, rotation, scale = 1, avatarId = "default", voiceVoice = "en-US-Neural2-F", greeting = "" }) => {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState("");
  const meshRef = useRef();
  
  const intent = useUserIntent();
  const [spokenZones, setSpokenZones] = useState(new Set());

  useEffect(() => {
    if ((intent.inferredIntent === 'engaged' || intent.inferredIntent === 'confused') && !spokenZones.has(intent.currentZone)) {
      setSpokenZones(prev => new Set(prev).add(intent.currentZone));
      
      const lines = {
        contango: "I see you're analyzing Contango Quant. Would you like a breakdown of the predictive algorithms?",
        legal: "Navigating legal frameworks can be complex. Shall I pull up the latest compliance matrix?",
        icebreaker: "Icebreaker creates instant rapport. Want me to generate a sample persona?",
        autopilot: "Autopilot is ready to execute your campaign. Just give me the command."
      };
      
      const line = lines[intent.currentZone] || `I noticed you're exploring the ${intent.currentZone} sector. Need any guidance?`;
      speak(line);
    }
  }, [intent.inferredIntent, intent.currentZone, spokenZones]);

  // Simulate Avatar Breathing/Idle
  useFrame((state) => {
    if (meshRef.current) {
      const t = state.clock.elapsedTime;
      // Slight breathing
      meshRef.current.position.y = Math.sin(t * 2) * 2;
      // Head bobbing if speaking
      if (isSpeaking) {
        meshRef.current.rotation.x = Math.sin(t * 15) * 0.05;
        meshRef.current.rotation.z = Math.cos(t * 10) * 0.02;
      } else {
        meshRef.current.rotation.x = THREE.MathUtils.lerp(meshRef.current.rotation.x, 0, 0.1);
        meshRef.current.rotation.z = THREE.MathUtils.lerp(meshRef.current.rotation.z, 0, 0.1);
      }
    }
  });

  useEffect(() => {
    if (greeting) {
      setTimeout(() => speak(greeting), 1000);
    }
  }, [greeting]);

  const speak = (text) => {
    setIsSpeaking(true);
    setTranscript(`AI Avatar: "${text}"`);
    
    // Simulate OmniVoice TTS duration based on text length
    const duration = Math.max(2000, text.length * 50);
    
    setTimeout(() => {
      setIsSpeaking(false);
      setTranscript("");
    }, duration);
  };

  const handleMicClick = () => {
    if (isListening) return;
    setIsListening(true);
    setTranscript("Listening... (Speak now via Handy STT)");
    
    // Simulate Handy STT Processing
    setTimeout(() => {
      setIsListening(false);
      setTranscript("User: \"Launch the Q3 marketing campaign.\"");
      
      // Avatar Responds
      setTimeout(() => {
        speak("Initializing Q3 marketing campaign across all channels. Autopilot engaged.");
      }, 1000);
    }, 3000);
  };

  return (
    <group position={position} rotation={rotation} scale={scale}>
      {/* HeyGem Photorealistic Mesh Placeholder */}
      <mesh ref={meshRef} position={[0, 50, 0]}>
        <cylinderGeometry args={[20, 20, 60, 32]} />
        <meshStandardMaterial 
          color={isSpeaking ? "#00ffff" : "#113344"} 
          emissive={isSpeaking ? "#00ffff" : "#000000"}
          emissiveIntensity={isSpeaking ? 0.5 : 0}
          roughness={0.2}
          metalness={0.8}
        />
        {/* Holographic glowing rings around the avatar */}
        <mesh position={[0, 0, 0]} rotation={[Math.PI/2, 0, 0]}>
          <torusGeometry args={[35, 1, 16, 64]} />
          <meshBasicMaterial color={isListening ? "#ff00ff" : "#00aaff"} transparent opacity={0.6} />
        </mesh>
      </mesh>

      {/* Voice Transcript / UI */}
      <Html position={[0, 100, 0]} center>
        <div className="w-[350px] flex flex-col items-center">
          {transcript && (
            <div className="bg-black/90 border border-cyan-500/50 p-4 rounded-xl mb-4 text-center">
              <p className="text-cyan-50 font-light text-lg">{transcript}</p>
            </div>
          )}
          
          <button 
            onClick={handleMicClick}
            disabled={isListening || isSpeaking}
            className={`w-16 h-16 rounded-full flex items-center justify-center border transition-all duration-300 ${
              isListening 
                ? "bg-fuchsia-500/20 border-fuchsia-500 animate-pulse" 
                : isSpeaking
                ? "bg-cyan-500/20 border-cyan-500 animate-pulse"
                : "bg-white/5 border-white/20 hover:bg-white/10 hover:border-white/40 cursor-pointer pointer-events-auto"
            }`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${isListening ? 'text-fuchsia-400' : 'text-white'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
            </svg>
          </button>
        </div>
      </Html>
    </group>
  );
};

export default AvatarSystem;
