import React, { useState, useRef, useEffect } from 'react';
import { hudStore } from './GenerativeHUD';

export const VoiceAgentSystem = ({ position = [0, 0, 0] }) => {
  const [isListening, setIsListening] = useState(false);
  const [audioLevel, setAudioLevel] = useState(0);
  
  const recognition = useRef(null);
  const audioContext = useRef(null);
  const analyser = useRef(null);
  const dataArray = useRef(null);
  const animationFrame = useRef(null);
  const localStream = useRef(null);
  const buttonRef = useRef(null);

  useEffect(() => {
    // Initialize SpeechRecognition if available
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognition.current = new SpeechRecognition();
      recognition.current.continuous = true;
      recognition.current.interimResults = true;
      
      recognition.current.onresult = (event) => {
        let interimTranscript = '';
        let finalTranscript = '';
        
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            finalTranscript += event.results[i][0].transcript;
          } else {
            interimTranscript += event.results[i][0].transcript;
          }
        }
        
        if (finalTranscript) {
          hudStore.pushMessage(`User: ${finalTranscript}`, 'user_voice');
          
          // Basic mock response logic
          setTimeout(() => {
            if (finalTranscript.toLowerCase().includes('hello')) {
              hudStore.pushMessage("Agent: Hello! I'm monitoring your session.", 'agent');
            } else if (finalTranscript.toLowerCase().includes('generate')) {
              hudStore.pushMessage("Agent: Generating component based on your request...", 'agent');
              hudStore.setComponent(
                <div className="bg-cyan-900/80 border border-cyan-400 p-8 rounded-xl backdrop-blur-md shadow-[0_0_30px_rgba(0,255,255,0.2)] text-white text-center">
                  <h3 className="text-2xl font-bold mb-4">Generated Dashboard</h3>
                  <p>I have built this UI block directly from your voice prompt.</p>
                </div>
              );
            }
          }, 500);
        }
      };

      recognition.current.onerror = (event) => {
        console.warn("Speech recognition error", event.error);
        if (event.error === 'not-allowed') {
          stopListening();
        }
      };
      
      recognition.current.onend = () => {
        // Automatically restart if we are supposed to be listening
        if (isListening) {
          try {
            recognition.current.start();
          } catch (e) {
            console.warn("Failed to restart recognition", e);
          }
        }
      };
    }

    return () => {
      stopListening();
    };
  }, [isListening]);

  const startListening = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      localStream.current = stream;
      setIsListening(true);
      
      if (recognition.current) {
        try {
          recognition.current.start();
        } catch(e) { /* already started */ }
      }
      
      hudStore.pushMessage("Voice Agent Activated. Always-on voice listening.", 'system');

      // Setup AudioContext for visualizer
      audioContext.current = new (window.AudioContext || window.webkitAudioContext)();
      const source = audioContext.current.createMediaStreamSource(stream);
      analyser.current = audioContext.current.createAnalyser();
      analyser.current.fftSize = 256;
      source.connect(analyser.current);
      
      const bufferLength = analyser.current.frequencyBinCount;
      dataArray.current = new Uint8Array(bufferLength);
      
      updateAudioLevel();
    } catch (err) {
      console.warn("Microphone access denied or failed", err);
      hudStore.pushMessage("Microphone access denied.", 'error');
    }
  };

  const stopListening = () => {
    setIsListening(false);
    
    if (recognition.current) {
      try {
        recognition.current.stop();
      } catch (e) {}
    }

    if (localStream.current) {
      localStream.current.getTracks().forEach(track => track.stop());
      localStream.current = null;
    }

    if (audioContext.current && audioContext.current.state !== 'closed') {
      audioContext.current.close();
    }
    
    if (animationFrame.current) {
      cancelAnimationFrame(animationFrame.current);
    }
    setAudioLevel(0);
    
    // If it was manually stopped by user
    hudStore.pushMessage("Voice Agent Deactivated. Defaulting to mouse movement tracking.", 'system');
  };

  const updateAudioLevel = () => {
    if (!analyser.current || !dataArray.current) return;
    
    analyser.current.getByteFrequencyData(dataArray.current);
    let sum = 0;
    for (let i = 0; i < dataArray.current.length; i++) {
      sum += dataArray.current[i];
    }
    const average = sum / dataArray.current.length;
    
    // Direct DOM manipulation to prevent 60 FPS React re-renders
    if (buttonRef.current) {
      const scale = 1 + (average / 128);
      buttonRef.current.style.transform = `scale(${scale})`;
    }
    
    animationFrame.current = requestAnimationFrame(updateAudioLevel);
  };

  return (
    <div className="flex flex-col items-center">
      <button
        ref={buttonRef}
        onClick={isListening ? stopListening : startListening}
        title={isListening ? "Disable Always-on Voice" : "Enable Always-on Voice"}
        className={`w-16 h-16 rounded-full flex items-center justify-center transition-all duration-300 backdrop-blur-md border pointer-events-auto cursor-pointer ${
          isListening 
            ? 'bg-fuchsia-600/40 border-fuchsia-400 shadow-[0_0_20px_rgba(217,70,239,0.5)]' 
            : 'bg-white/10 border-white/30 hover:bg-white/20'
        }`}
        style={{
          transform: `scale(1)`,
        }}
      >
        <svg xmlns="http://www.w3.org/2000/svg" className={`h-8 w-8 ${isListening ? 'text-white' : 'text-gray-300'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
          {isListening ? (
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          ) : (
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
          )}
        </svg>
      </button>
      
      {isListening && (
        <div className="mt-4 text-fuchsia-300 font-mono text-xs tracking-widest animate-pulse pointer-events-none text-center">
          VOICE AGENT ACTIVE<br/>
          <span className="text-[10px] text-fuchsia-400/70">Say "Generate a dashboard"</span>
        </div>
      )}
      {!isListening && (
        <div className="mt-4 text-gray-500 font-mono text-[10px] tracking-widest pointer-events-none text-center">
          MOUSE TRACKING ACTIVE
        </div>
      )}
    </div>
  );
};

export default VoiceAgentSystem;
